import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {
  FileIcon,
  FileMediaIcon,
  ImageIcon,
  TrashIcon,
  UnmuteIcon,
  UploadIcon,
  VideoIcon,
  XIcon,
} from '@primer/octicons-react'
import {ActionList, ConfirmationDialog, Dialog, IconButton} from '@primer/react'
import {useEffect, useMemo, useRef, useState} from 'react'

import {useFilesContext} from '../../../contexts/FilesContext'
import {useFileSyncerContext} from '../../../contexts/FileSyncerContext'
import {ReadOnlyKey, useReadOnly} from '../../../hooks/use-read-only'
import {useIterateAnalytics} from '../../../telemetry/use-analytics'
import workbenchConsole from '../../../utilities/console'
import {
  cleanupBlobUrl,
  getAssetDirectory,
  getFileCategory,
  getReadableFileSize,
  getSupportedAssetExtensions,
  isInAssetSubdirectory,
  readMediaFile,
} from '../../../utilities/media-utils'
import {EditorLoadingSkeleton} from '../../EditorLoadingSkeleton'
import {MediaPreview} from '../../MediaPreview/MediaPreview'
import {Section} from '../Section'
import styles from './AssetsPanel.module.css'

interface Asset {
  name: string
  size: string
  content?: string // Make content optional since we'll lazy load it
  filePath: string // Store the full file path for lazy loading
}

const assetsLocation = 'src/assets/'

const getAssetInfo = (asset: Asset, includeMedia: boolean): string => {
  const extension = asset.name.split('.').pop()?.toLowerCase() || ''
  const size = asset.size || 'unknown size'

  const type = getFileCategory(extension, includeMedia)

  return `${type} · ${size}`
}

const getAssetIcon = (asset: Asset, includeMedia: boolean) => {
  const extension = asset.name.split('.').pop()?.toLowerCase() || ''
  const category = getFileCategory(extension, includeMedia)

  switch (category) {
    case 'Image':
      return <ImageIcon />
    case 'Video':
      return <VideoIcon />
    case 'Audio':
      return <UnmuteIcon />
    case 'Document':
      return <FileIcon />
    default:
      return <FileMediaIcon />
  }
}

export function AssetsPanel() {
  const {getFileList, editFile, writeFileBytes} = useFilesContext()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const {forceFileTreeRefresh, getFileSyncerV2, syncerMode} = useFileSyncerContext()
  const fileSyncerConnected = syncerMode === 'codespace'
  const includeMedia = useFeatureFlag('spark_assets_include_media')
  const increaseSizeLimit = useFeatureFlag('spark_assets_increase_size_limit')
  const MAX_FILE_SIZE = (increaseSizeLimit ? 10 : 1) * 1024 * 1024

  const [isFetching, setIsFetching] = useState<boolean>(true)

  const files = useMemo(() => {
    return getFileList().map(file => file.path)
  }, [getFileList])

  const [assets, setAssets] = useState<Asset[]>([])
  const [openAsset, setOpenAsset] = useState<Asset>()
  const [loadingAssetContent, setLoadingAssetContent] = useState<boolean>(false)
  const [hoveredAsset, setHoveredAsset] = useState<string | null>(null)
  const [isDeleteConfirmationOpen, setIsDeleteConfirmationOpen] = useState<boolean>(false)
  const [assetToDelete, setAssetToDelete] = useState<Asset | null>(null)

  // Track blob URLs for cleanup
  const blobUrlsRef = useRef<Set<string>>(new Set())

  const readOnly = useReadOnly(ReadOnlyKey.ASSETS_PANEL)
  const isUploadDisabled = readOnly || !fileSyncerConnected

  useEffect(() => {
    run()

    async function run() {
      setIsFetching(true)
      const newAssets = []
      for (const file of files) {
        if (file.startsWith(assetsLocation)) {
          // Extract the relative path from the assets location
          const relativePath = file.slice(assetsLocation.length)

          // Check if it's in one of our asset subdirectories OR directly in the assets root
          if (isInAssetSubdirectory(relativePath) || !relativePath.includes('/')) {
            // Extract just the filename from the subdirectory path or use the full relative path for root files
            const fileName = relativePath.split('/').pop() || relativePath
            newAssets.push({
              name: fileName,
              size: 'Loading...', // We'll update this when content is loaded
              filePath: file,
            })
          }
        }
      }
      setIsFetching(false)
      setAssets(newAssets)
    }
  }, [files, getFileSyncerV2])

  const {iterateStarted, iterateSuccess} = useIterateAnalytics('assets_panel')

  // Function to load asset content when dialog is opened
  const loadAssetContent = async (asset: Asset): Promise<Asset> => {
    if (asset.content) {
      return asset // Already loaded
    }

    setLoadingAssetContent(true)
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer) {
      setLoadingAssetContent(false)
      return asset
    }

    try {
      const content = await readMediaFile(asset.filePath, fileSyncer, false)

      // Track blob URLs for cleanup
      if (content && content.startsWith('blob:')) {
        blobUrlsRef.current.add(content)
      }

      const updatedAsset = {
        ...asset,
        content: content || '',
        size: getReadableFileSize(content || ''),
      }

      // Update the asset in the assets array
      setAssets(prev => prev.map(a => (a.name === asset.name ? updatedAsset : a)))

      // Also update the currently open asset
      setOpenAsset(updatedAsset)

      setLoadingAssetContent(false)
      return updatedAsset
    } catch {
      setLoadingAssetContent(false)
      return asset
    }
  }

  const uploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const telemetryProperties = iterateStarted()
      const selectedFiles = Array.from(e.target.files)

      // Check file sizes and filter out files that are too large
      const validFiles: File[] = []
      const invalidFiles: string[] = []

      for (const file of selectedFiles) {
        if (file.size > MAX_FILE_SIZE) {
          invalidFiles.push(`${file.name} (${getReadableFileSize(file.size)})`)
        } else {
          validFiles.push(file)
        }
      }

      // Show alert for invalid files if any
      if (invalidFiles.length > 0) {
        alert(
          `The following files exceed the maximum limit of ${
            MAX_FILE_SIZE / (1024 * 1024)
          }MB and will be skipped:\n\n${invalidFiles.join('\n')}`,
        )
      }

      // Process valid files
      if (validFiles.length > 0) {
        try {
          // Process all files concurrently
          await Promise.all(
            validFiles.map(file => {
              return new Promise<void>((resolve, reject) => {
                const assetDir = getAssetDirectory(file.name, includeMedia)
                const filePath = `${assetsLocation}${assetDir}/${file.name}`
                const reader = new FileReader()

                reader.onload = async () => {
                  try {
                    // For binary files, we want to use the ArrayBuffer result
                    if (reader.result instanceof ArrayBuffer) {
                      // Create a Uint8Array from the ArrayBuffer
                      const uint8Array = new Uint8Array(reader.result)

                      // Save as raw binary - pass the Uint8Array directly
                      await writeFileBytes({filePath, content: uint8Array})
                    } else if (typeof reader.result === 'string') {
                      // For text files
                      await editFile({filePath, newFileContent: reader.result})
                    }

                    forceFileTreeRefresh()
                    iterateSuccess(telemetryProperties)
                    resolve()
                  } catch (error) {
                    reject(error)
                  }
                }

                reader.onerror = () => reject(new Error(`Failed to read file: ${file.name}`))

                // Read as binary data instead of DataURL
                reader.readAsArrayBuffer(file)
              })
            }),
          )

          forceFileTreeRefresh()
          iterateSuccess(telemetryProperties)
        } catch (err) {
          workbenchConsole.error(err)
        }
      }

      // Clear the input value to allow the same files to be uploaded again if needed
      e.target.value = ''
    }
  }

  const triggerFileInput = () => {
    fileInputRef.current?.click()
  }

  const deleteAsset = (asset: Asset) => {
    setAssetToDelete(asset)
    setIsDeleteConfirmationOpen(true)
  }

  const deleteAssetFile = async (asset: Asset) => {
    const fileSyncer = getFileSyncerV2()
    if (!fileSyncer) {
      return
    }

    try {
      await fileSyncer.deleteFile(asset.filePath)
      // Remove the asset from the local state
      setAssets(prev => prev.filter(a => a.name !== asset.name))
      // Close the dialog if the deleted asset is currently open
      if (openAsset?.name === asset.name) {
        setOpenAsset(undefined)
      }
      // Refresh the file tree
      forceFileTreeRefresh()
    } catch (error) {
      workbenchConsole.error('Error deleting file:', error)
      // Could show an error message here instead of just logging
    }
  }

  const downloadAsset = (asset: Asset) => {
    if (!asset.content) {
      return
    }

    try {
      // Convert base64 content to blob
      const contentParts = asset.content.split(',')
      if (contentParts.length < 2 || !contentParts[1]) {
        return
      }
      const byteCharacters = atob(contentParts[1])
      const byteNumbers = new Array(byteCharacters.length)
      for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i)
      }
      const byteArray = new Uint8Array(byteNumbers)
      const blob = new Blob([byteArray])

      // Create download link
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = asset.name
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
    } catch (error) {
      workbenchConsole.error('Error downloading file:', error)
    }
  }

  // Cleanup blob URLs when component unmounts
  useEffect(() => {
    const urlsSet = blobUrlsRef.current
    return () => {
      // Clean up all blob URLs
      cleanupBlobUrl(Array.from(urlsSet))
    }
  }, [])

  if (assets.length === 0) {
    return (
      <div className="mt-3">
        <Section title="Assets" showTitle={false} loading={false} readOnly={isUploadDisabled}>
          <Section.PrimaryAction icon={UploadIcon} onSelect={triggerFileInput}>
            Upload files
          </Section.PrimaryAction>
          <input
            type="file"
            ref={fileInputRef}
            onChange={uploadFile}
            className="d-none"
            accept={getSupportedAssetExtensions(includeMedia).join(',')}
            multiple
          />
          <Section.Items>
            <p className="fgColor-muted text-small mt-1 mb-0">
              Upload images, documents, audio, and video files to use them in your spark.
            </p>
            <ActionList>
              {[
                {
                  name: 'company-logo.png',
                  description: 'Image · 24 KB · PNG',
                  opacity: 0.6,
                  icon: <ImageIcon />,
                },
                {
                  name: 'restaurant-menu.pdf',
                  description: 'PDF · 320 KB',
                  opacity: 0.45,
                  icon: <FileIcon />,
                },
                {
                  name: 'confirmation-sound.mp3',
                  description: 'Audio · 982 KB · MP3',
                  opacity: 0.3,
                  icon: <UnmuteIcon />,
                },
                {
                  name: 'hero-video.mp4',
                  description: 'Video · 4 MB · MP4',
                  opacity: 0.18,
                  icon: <VideoIcon />,
                },
              ].map(({name, description, opacity, icon}) => (
                <ActionList.Item className={styles.listItem} key={name} disabled style={{opacity}}>
                  <ActionList.LeadingVisual>{icon}</ActionList.LeadingVisual>
                  {name}
                  <ActionList.Description variant="block">{description}</ActionList.Description>
                </ActionList.Item>
              ))}
            </ActionList>
          </Section.Items>
        </Section>
      </div>
    )
  }

  return (
    <div className="mt-3">
      <Section title="Assets" showTitle={false} readOnly={isUploadDisabled} loading={isFetching || isUploadDisabled}>
        <Section.PrimaryAction icon={UploadIcon} onSelect={triggerFileInput}>
          Upload files
        </Section.PrimaryAction>
        <input
          type="file"
          ref={fileInputRef}
          onChange={uploadFile}
          className="d-none"
          accept={getSupportedAssetExtensions(includeMedia).join(',')}
          multiple
        />

        <ActionList>
          {assets.map(asset => (
            <ActionList.Item
              key={asset.name}
              className={styles.listItem}
              onSelect={() => {
                // Show dialog immediately
                setOpenAsset(asset)
                // Start loading content in the background if not already loaded
                if (!asset.content) {
                  loadAssetContent(asset)
                }
              }}
              onMouseEnter={() => setHoveredAsset(asset.name)}
              onMouseLeave={() => setHoveredAsset(null)}
            >
              <ActionList.LeadingVisual>{getAssetIcon(asset, includeMedia)}</ActionList.LeadingVisual>
              {asset.name}
              <ActionList.Description variant="block">{getAssetInfo(asset, includeMedia)}</ActionList.Description>
              {hoveredAsset === asset.name && (
                <ActionList.TrailingAction
                  label={`Delete ${asset.name}`}
                  icon={TrashIcon}
                  onMouseEnter={() => setHoveredAsset(asset.name)}
                  onMouseLeave={() => setHoveredAsset(null)}
                  onClick={(e: React.MouseEvent) => {
                    e.stopPropagation() // Prevent opening the dialog
                    deleteAsset(asset)
                  }}
                />
              )}
            </ActionList.Item>
          ))}
        </ActionList>
      </Section>

      {openAsset && (
        <Dialog
          onClose={() => {
            setOpenAsset(undefined)
          }}
          renderHeader={() => (
            <div className="p-3 border-bottom">
              <div className="d-flex flex-justify-between flex-items-center">
                <span className={styles.dialogTitle}>{openAsset.name}</span>
                <IconButton
                  aria-label="Close asset dialog"
                  size="small"
                  variant="invisible"
                  icon={XIcon}
                  onClick={() => {
                    setOpenAsset(undefined)
                  }}
                />
              </div>

              <span className={styles.dialogSubtitle}>{getAssetInfo(openAsset, includeMedia)}</span>
            </div>
          )}
          footerButtons={[
            {
              buttonType: 'default',
              content: 'Download',
              onClick: () => downloadAsset(openAsset),
            },
            {
              buttonType: 'danger',
              content: 'Delete',
              onClick: () => {
                setOpenAsset(undefined)
                deleteAsset(openAsset)
              },
            },
          ]}
        >
          {!openAsset.content || loadingAssetContent ? (
            <EditorLoadingSkeleton fadeIn />
          ) : (
            <MediaPreview src={openAsset.content} filePath={openAsset.filePath} alt={`${openAsset.name} preview`} />
          )}
        </Dialog>
      )}

      {isDeleteConfirmationOpen && assetToDelete && (
        <ConfirmationDialog
          title="Delete asset"
          onClose={gesture => {
            if (gesture === 'confirm') {
              deleteAssetFile(assetToDelete)
            }
            setIsDeleteConfirmationOpen(false)
            setAssetToDelete(null)
          }}
          confirmButtonContent="Delete"
          confirmButtonType="danger"
        >
          Are you sure you want to delete {assetToDelete.name}?
        </ConfirmationDialog>
      )}
    </div>
  )
}

try{ AssetsPanel.displayName ||= 'AssetsPanel' } catch {}
try{ MAX_FILE_SIZE.displayName ||= 'MAX_FILE_SIZE' } catch {}